BEGIN
  -- ── Décor ───────────────────────────────────────────────────────────
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  INSERT INTO public.network_administrators (user_id, status) VALUES (v_admin, 'active');
  INSERT INTO public.catalog_ref_source_partners (code, label, sort_order, is_active)
  VALUES ('other_partner', 'Outro parceiro', 80, true) ON CONFLICT (code) DO NOTHING;
  UPDATE public.libraries SET tombo_pattern = '{"prefix": "L6-T-", "year": false, "pad": 4}'::jsonb WHERE id = v_lib;
  INSERT INTO public.libraries (id, slug, name, is_active, visibility_level, tombo_pattern)
  VALUES (gen_random_uuid(), 'essai-h21-l6a-b', 'Essai H21 lot 6a — B', true, 'private',
          '{"prefix": "L6B-T-", "year": false, "pad": 4}'::jsonb)
  RETURNING id INTO v_libB;
  UPDATE public.user_library_memberships SET status = 'inactive', is_primary = false WHERE user_id = v_coordB;
  INSERT INTO public.user_library_memberships (user_id, library_id, role, status, is_primary)
  VALUES (v_coordB, v_libB, 'coordenador', 'active', true);

  INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
  VALUES ('L6 PMB 8.1 (fixtures)', v_lib, 'mapeada', 'own_catalog', true) RETURNING id INTO v_src;

  -- Premier import : promu, révisé, publié.
  INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
  VALUES (v_src, v_lib, 'essai/l6-pmb.iso', 'l6-pmb.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run1;
  INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
  SELECT v_run1, r.row_no, r.external_key, r.item_type, r.title, r.subtitle, r.responsibility_statement, r.authors, r.publisher, r.place_of_publication, r.publication_year, r.edition_statement, r.language, r.isbn, r.issn, r.subjects, r.raw_payload, r.normalized_payload, 'new_record', 'accept_new'
    FROM jsonb_to_recordset(v_pmb)
      AS r(row_no integer, external_key text, item_type text, title text, subtitle text, responsibility_statement text, authors jsonb, publisher text, place_of_publication text, publication_year text, edition_statement text, language text, isbn text, issn text, subjects jsonb, raw_payload jsonb, normalized_payload jsonb);
  v_res := public.fn_import_promote(v_run1, ARRAY['new_record'], ARRAY['accept_new']);
  v_lot1 := (v_res->>'batch_id')::bigint;
  UPDATE public.book_drafts SET bib_ref = 'L6-PMB-REF-' || id WHERE batch_id = v_lot1 AND bib_ref IS NULL;
  v_res := public.fn_batch_review_request(v_lot1);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  PERFORM public.fn_batch_review_verdict((v_res->>'review_id')::bigint, 'approved', NULL);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  PERFORM public.publish_catalog_batch(v_lot1);
  IF (SELECT count(*) FROM public.book_drafts WHERE batch_id = v_lot1 AND status = 'published') <> 64 THEN
    RAISE EXCEPTION 'decor : publication incomplete';
  END IF;
  SELECT max(d.published_book_id) FILTER (WHERE s.row_no = 1), max(d.published_book_id) FILTER (WHERE s.row_no = 2),
         max(d.published_book_id) FILTER (WHERE s.row_no = 4), max(d.published_book_id) FILTER (WHERE s.row_no = 5),
         max(d.published_book_id) FILTER (WHERE s.row_no = 6), max(d.published_book_id) FILTER (WHERE s.row_no = 7),
         max(d.published_book_id) FILTER (WHERE s.row_no = 9), max(d.published_book_id) FILTER (WHERE s.row_no = 10)
    INTO b1, b2, b4, b5, b6, b7, b9, b10
    FROM ingest.partner_catalog_staging_rows s
    JOIN ingest.partner_catalog_row_to_draft m ON m.staging_row_id = s.id
    JOIN public.book_drafts d ON d.id = m.draft_id
   WHERE s.run_id = v_run1;
  SELECT max(e.id) FILTER (WHERE e.source_item_code = '33700004388761'), max(e.id) FILTER (WHERE e.source_item_code = '33700003470461'),
         max(e.id) FILTER (WHERE e.source_item_code = '33700003719453'), max(e.id) FILTER (WHERE e.source_item_code = '33700003550072'),
         max(e.id) FILTER (WHERE e.source_item_code = '33700004389030'), max(e.id) FILTER (WHERE e.source_item_code = '33700003669468'),
         max(e.id) FILTER (WHERE e.source_item_code = '33700003669484'), max(e.id) FILTER (WHERE e.source_item_code = '33700003669485')
    INTO e1, e4, e5, e6, e7a, e8, e9, e10
    FROM public.exemplares e WHERE e.library_id = v_lib;

  -- ── Le réimport : les mêmes lignes, retouchées dans le fichier ─────────
  INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
  VALUES (v_src, v_lib, 'essai/l6-pmb-reimport.iso', 'l6-pmb-reimport.iso', 'marc_iso2709', 'parsed') RETURNING id INTO v_run2;
  INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
  SELECT v_run2, r.row_no, r.external_key, r.item_type, r.title, r.subtitle, r.responsibility_statement, r.authors, r.publisher, r.place_of_publication, r.publication_year, r.edition_statement, r.language, r.isbn, r.issn, r.subjects, r.raw_payload, r.normalized_payload, 'unreviewed', 'pending'
    FROM jsonb_to_recordset(v_pmb)
      AS r(row_no integer, external_key text, item_type text, title text, subtitle text, responsibility_statement text, authors jsonb, publisher text, place_of_publication text, publication_year text, edition_statement text, language text, isbn text, issn text, subjects jsonb, raw_payload jsonb, normalized_payload jsonb);
  SELECT max(id) FILTER (WHERE row_no = 1), max(id) FILTER (WHERE row_no = 2), max(id) FILTER (WHERE row_no = 3),
         max(id) FILTER (WHERE row_no = 5), max(id) FILTER (WHERE row_no = 6), max(id) FILTER (WHERE row_no = 7),
         max(id) FILTER (WHERE row_no = 8), max(id) FILTER (WHERE row_no = 9), max(id) FILTER (WHERE row_no = 10),
         max(id) FILTER (WHERE row_no = 11), max(id) FILTER (WHERE row_no = 20)
    INTO r1, r2, r3, r5, r6, r7, r8, r9, r10, r11, r20
    FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2;
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{items}', (normalized_payload->'items')
           || '[{"source_item_code": "L6-AJOUT-2", "source_item_id": "9002", "call_number": "L6 A2"}]'::jsonb)
   WHERE id = r2;
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{items}', '[{"source_item_code": null, "source_item_id": "3", "call_number": "L6 SANS"}]'::jsonb)
   WHERE id = r3;
  -- l'exemplaire du rang 4 passe, dans PMB, sous la notice du rang 5 ; le rang 5
  -- change aussi d'année (T15 : « Préparer » traite une ligne signalée)
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{items}', (normalized_payload->'items')
           || '[{"source_item_code": "33700003470461", "source_item_id": "4", "call_number": "L6 DEPL"}]'::jsonb),
         publication_year = '2015'
   WHERE id = r5;
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{items}', '[{"source_item_code": "L6-NOUVEAU-6", "source_item_id": "6", "call_number": "L6 REET"}]'::jsonb)
   WHERE id = r6;
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{items,0,source_item_id}', '"999"'::jsonb)
   WHERE id = r7;
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{items,0,source_item_id}', '"10"'::jsonb)
   WHERE id = r8;
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{items}', (normalized_payload->'items')
           || '[{"source_item_code": "L6-CORB-10", "source_item_id": "9010", "call_number": "L6 CORB"}]'::jsonb)
   WHERE id = r10;
  UPDATE ingest.partner_catalog_staging_rows SET publication_year = '2011' WHERE id = r11;
  PERFORM ingest.fn_match_partner_catalog_run(v_run2);
  IF (SELECT count(*) FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND match_status = 'known_record') <> 64
     OR (SELECT proposed_book_id FROM ingest.partner_catalog_staging_rows WHERE id = r5) IS DISTINCT FROM b5
     OR e1 IS NULL OR e4 IS NULL OR e9 IS NULL OR e10 IS NULL THEN
    RAISE EXCEPTION 'decor : reimport non reconnu';
  END IF;

  -- L'empreinte du catalogue : notices, fonds, exemplaires, identifiants, circulation.
  v_ref := 'select md5(concat_ws(''|'',
      (select string_agg(md5(to_jsonb(b)::text), '','' order by b.id) from public.books b),
      (select string_agg(md5(to_jsonb(h)::text), '','' order by h.id) from public.book_holdings h),
      (select string_agg(md5(to_jsonb(e)::text), '','' order by e.id) from public.exemplares e),
      (select string_agg(md5(to_jsonb(x)::text), '','' order by x.id) from public.book_external_ids x),
      (select string_agg(md5(to_jsonb(i)::text), '','' order by i.id) from public.emprestimo_itens_v2 i),
      (select string_agg(md5(to_jsonb(l)::text), '','' order by l.id) from public.reserva_linhas_v2 l)))';

  -- ── T1 ──────────────────────────────────────────────────────────────
  v_t := 'T1 premiere publication : code, expl_id (996), source et run sur chaque exemplaire ; constat de la promotion ; trace aux brouillons';
  BEGIN
    IF (SELECT count(*) FROM public.exemplares e WHERE e.library_id = v_lib AND e.import_run_id = v_run1) = 46
       AND NOT EXISTS (SELECT 1 FROM public.exemplares e WHERE e.import_run_id = v_run1
                        AND (e.import_source_id IS DISTINCT FROM v_src OR e.source_item_id IS NULL OR e.source_item_code IS NULL))
       -- chaque exemplaire a l'expl_id de SON exemplaire du fichier
       AND NOT EXISTS (SELECT 1 FROM jsonb_to_recordset(v_pmb) r(normalized_payload jsonb)
                         CROSS JOIN LATERAL jsonb_array_elements(r.normalized_payload->'items') i(v)
                        WHERE NOT EXISTS (SELECT 1 FROM public.exemplares e
                                           WHERE e.library_id = v_lib AND e.source_item_code = i.v->>'source_item_code'
                                             AND e.source_item_id = i.v->>'source_item_id' AND e.import_run_id = v_run1))
       AND (SELECT e.source_item_id FROM public.exemplares e WHERE e.id = e1) = '1'
       AND (SELECT e.source_item_id FROM public.exemplares e WHERE e.id = e10) = '11'
       AND (SELECT count(*) FROM ingest.partner_catalog_staging_rows sr
              CROSS JOIN LATERAL jsonb_array_elements(sr.exemplaires_constat->'items') x(v)
             WHERE sr.run_id = v_run1 AND x.v->>'verdict' = 'nouveau' AND x.v->>'brouillon_cree' IS NOT NULL) = 46
       AND (SELECT count(*) FROM ingest.partner_catalog_staging_rows sr
             WHERE sr.run_id = v_run1 AND sr.exemplaires_constat->>'via' = 'promotion'
               AND (sr.exemplaires_constat->>'batch_id')::bigint = v_lot1
               AND sr.exemplaires_constat->>'library_id' = v_lib::text) = 42
       AND (SELECT count(*) FROM public.exemplar_drafts x
             WHERE x.batch_id = v_lot1 AND x.import_run_id = v_run1 AND x.import_source_id = v_src
               AND x.source_item_id IS NOT NULL AND x.status = 'published') = 46
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : exemplaires du run '
         ||(SELECT count(*) FROM public.exemplares e WHERE e.import_run_id = v_run1)||' / sans expl_id '
         ||(SELECT count(*) FROM public.exemplares e WHERE e.import_run_id = v_run1 AND e.source_item_id IS NULL)); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T2 ──────────────────────────────────────────────────────────────
  v_t := 'T2 Rapprocher [1, 2] rejoint le lot ouvert du run ; seul nouveau cree (code, expl_id, source, run) ; 1 rejetee d''office';
  DECLARE v_prep jsonb;
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    PERFORM public.fn_import_recomparer(v_run2, ARRAY[r11]);
    v_prep := public.fn_import_preparer_mises_a_jour(v_run2, ARRAY[r11]);
    EXECUTE 'RESET ROLE';
    v_lotL := (v_prep->>'batch_id')::bigint;
    v_nb := (SELECT count(*) FROM public.catalog_batches);
    v_nx := (SELECT count(*) FROM public.exemplar_drafts);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_reconcile_duplicates(v_run2, ARRAY[r1, r2]);
    EXECUTE 'RESET ROLE';
    d2 := (SELECT x.id FROM public.exemplar_drafts x WHERE x.import_staging_row_id = r2 AND x.status = 'draft');
    IF v_lotL IS NOT NULL AND (v_res->>'batch_id')::bigint = v_lotL AND (v_res->>'batch_joined')::boolean
       AND (v_res->>'created_items')::int = 1 AND (v_res->>'created_exemplar_drafts')::int = 1
       AND (v_res->>'rows_already_held')::int = 1 AND (v_res->>'items_skipped_code_taken')::int = 3
       AND (v_res->>'rows_signalled')::int = 0
       AND v_res->'verdicts' = '{"nouveau": 1, "deja_la": 3, "deja_en_brouillon": 0, "sans_code": 0, "deplace": 0, "reetiquete": 0, "code_repris": 0}'::jsonb
       AND (SELECT count(*) FROM public.catalog_batches) = v_nb
       AND (SELECT count(*) FROM public.exemplar_drafts) = v_nx + 1
       AND (SELECT x.source_item_code = 'L6-AJOUT-2' AND x.source_item_id = '9002' AND x.import_source_id = v_src
                   AND x.import_run_id = v_run2 AND x.batch_id = v_lotL AND x.target_library_id = v_lib
                   AND x.book_draft_id IS NULL AND x.shelf_location = 'L6 A2'
                   AND x.target_bib_ref = (SELECT b.bib_ref FROM public.books b WHERE b.id = b2)
              FROM public.exemplar_drafts x WHERE x.id = d2)
       AND (SELECT created_exemplar_draft_id FROM ingest.partner_catalog_staging_rows WHERE id = r2) = d2
       AND (SELECT jsonb_agg(x.v->>'verdict' ORDER BY (x.v->>'n')::int) FROM ingest.partner_catalog_staging_rows sr
              CROSS JOIN LATERAL jsonb_array_elements(sr.exemplaires_constat->'items') x(v) WHERE sr.id = r2)
           = '["deja_la", "deja_la", "nouveau"]'::jsonb
       AND (SELECT (sr.exemplaires_constat->'items'->2->>'brouillon_cree')::bigint = d2
                   AND sr.exemplaires_constat->'items'->2->>'expl_id' = '9002'
                   AND (sr.exemplaires_constat->>'batch_id')::bigint = v_lotL AND sr.exemplaires_constat->>'via' = 'rapprochement'
              FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = r2)
       -- la ligne 1 : rien à apporter — rejetée d'office, note reconnue
       AND (SELECT sr.editorial_decision = 'reject' AND sr.review_status = 'rejected' AND sr.created_exemplar_draft_id IS NULL
                   AND sr.editorial_note LIKE 'Todos os exemplares desta linha ja estao na biblioteca%'
                   AND NOT ingest.fn_h21_rejet_par_choix(sr.editorial_decision, sr.editorial_note, sr.discarded_draft_id)
                   AND sr.exemplaires_constat->'items'->0->>'verdict' = 'deja_la'
                   AND (sr.exemplaires_constat->'items'->0->>'exemplar_id')::bigint = e1
                   AND (sr.exemplaires_constat->'items'->0->>'book_id')::bigint = b1
                   AND (sr.exemplaires_constat->>'batch_id')::bigint = v_lotL
              FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = r1)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : lot du run='||coalesce(v_lotL::text, '∅')
         ||' res='||left(coalesce((v_res - 'run')::text, 'NULL'), 400)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T3 ──────────────────────────────────────────────────────────────
  v_t := 'T3 Rapprocher [3, 5, 6, 7, 8] : sans code, deplace, reetiquete, code repris — signales, AUCUNE ecriture, aucun brouillon';
  DECLARE v_c jsonb;
  BEGIN
    -- l'exemplaire du rang 8 n'a pas d'expl_id (publié avant le lot 6a) : seul
    -- l'expl_id du fichier, porté par l'exemplaire du rang 9, dit « code repris »
    UPDATE public.exemplares SET source_item_id = NULL WHERE id = e8;
    EXECUTE v_ref INTO v_avant;
    v_nb := (SELECT count(*) FROM public.catalog_batches);
    v_nx := (SELECT count(*) FROM public.exemplar_drafts);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_reconcile_duplicates(v_run2, ARRAY[r3, r5, r6, r7, r8]);
    EXECUTE 'RESET ROLE';
    EXECUTE v_ref INTO v_apres;
    SELECT jsonb_object_agg(sr.id::text, sr.exemplaires_constat->'items') INTO v_c
      FROM ingest.partner_catalog_staging_rows sr WHERE sr.id IN (r3, r5, r6, r7, r8);
    IF v_apres = v_avant
       AND (SELECT count(*) FROM public.catalog_batches) = v_nb
       AND (SELECT count(*) FROM public.exemplar_drafts) = v_nx
       AND v_res->>'batch_id' IS NULL AND (v_res->>'created_items')::int = 0
       AND (v_res->>'rows_signalled')::int = 5 AND (v_res->>'rows_already_held')::int = 0
       AND v_res->'verdicts' = '{"nouveau": 0, "deja_la": 2, "deja_en_brouillon": 0, "sans_code": 1, "deplace": 1, "reetiquete": 1, "code_repris": 2}'::jsonb
       AND (SELECT count(*) FROM ingest.partner_catalog_staging_rows
             WHERE id IN (r3, r5, r6, r7, r8) AND editorial_decision = 'accept_duplicate' AND review_status = 'approved'
               AND NOT selected_for_draft AND created_exemplar_draft_id IS NULL AND created_book_draft_id IS NULL
               AND (exemplaires_constat->>'batch_id')::bigint = v_lotL) = 5
       AND v_c->(r3::text)->0 @> '{"verdict": "sans_code", "code": null, "expl_id": "3", "cote": "L6 SANS"}'::jsonb
       AND v_c->(r5::text)->0 @> jsonb_build_object('verdict', 'deja_la', 'exemplar_id', e5, 'book_id', b5)
       AND v_c->(r5::text)->1 @> jsonb_build_object('verdict', 'deplace', 'exemplar_id', e4, 'book_id', b4,
                                                    'code', '33700003470461', 'expl_id', '4')
       AND v_c->(r6::text)->0 @> jsonb_build_object('verdict', 'reetiquete', 'exemplar_id', e6, 'book_id', b6,
                                                    'ancien_code', '33700003550072', 'code', 'L6-NOUVEAU-6')
       AND v_c->(r7::text)->0 @> jsonb_build_object('verdict', 'code_repris', 'exemplar_id', e7a, 'autre_expl_id', '7')
       AND v_c->(r7::text)->1 @> '{"verdict": "deja_la"}'::jsonb
       AND v_c->(r8::text)->0 @> jsonb_build_object('verdict', 'code_repris', 'exemplar_id', e8, 'exemplar_id_expl', e9)
       AND v_c->(r8::text)->0->'autre_expl_id' = 'null'::jsonb
       -- l'exemplaire déplacé dans PMB est resté sur sa notice dans AnarBib
       AND (SELECT h.book_id FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id = e4) = b4
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : catalogue '||CASE WHEN v_apres = v_avant THEN 'intact' ELSE 'CHANGE' END
         ||' res='||left(coalesce((v_res - 'run')::text, 'NULL'), 300)||' constats='||left(coalesce(v_c::text, 'NULL'), 900)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T4 ──────────────────────────────────────────────────────────────
  v_t := 'T4 la liste : les exemplaires du fichier et leur verdict ; la notice ou est l''exemplaire deplace ; sans constat, sans verdict';
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    SELECT jsonb_object_agg(l.id::text, coalesce(l.exemplaires, 'null'::jsonb)) INTO v_res
      FROM public.fn_import_list_run_rows(v_run2) l WHERE l.id IN (r2, r5, r9, r20);
    EXECUTE 'RESET ROLE';
    IF v_res->(r5::text)->1->>'verdict' = 'deplace'
       AND v_res->(r5::text)->1->>'book_titulo' = (SELECT titulo FROM public.books WHERE id = b4)
       AND jsonb_array_length(v_res->(r2::text)) = 3
       AND (v_res->(r2::text)->2->>'brouillon_cree')::bigint = d2
       -- sans constat (ligne jamais rapprochée) : la liste du fichier, sans verdict
       AND jsonb_array_length(v_res->(r9::text)) = 1 AND NOT (v_res->(r9::text)->0 ? 'verdict')
       AND v_res->(r9::text)->0->>'expl_id' = '10' AND v_res->(r9::text)->0->>'code' = '33700003669484'
       AND (v_res->(r9::text)->0->>'n')::int = 1
       AND v_res->(r20::text) = 'null'::jsonb
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce(v_res::text, 'NULL'), 600)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T5 ──────────────────────────────────────────────────────────────
  v_t := 'T5 rapport de revision du lot du run : exemplaires ecartes et pourquoi ; absent sans ecart';
  DECLARE v_rap jsonb; v_rap1 jsonb;
  BEGIN
    v_rap := public.fn_batch_review_report(v_lotL);
    v_rap1 := public.fn_batch_review_report(v_lot1);
    IF (v_rap->'items_set_aside'->>'count')::int = 10
       AND (v_rap->'items_set_aside'->>'rows')::int = 7
       AND v_rap->'items_set_aside'->'counts' = '{"deja_la": 5, "deja_en_brouillon": 0, "sans_code": 1, "deplace": 1, "reetiquete": 1, "code_repris": 2}'::jsonb
       AND jsonb_array_length(v_rap->'items_set_aside'->'examples') = 10
       AND v_rap->'items_set_aside'->'examples'->0->>'verdict' = 'code_repris'
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_rap->'items_set_aside'->'examples') e
                    WHERE e->>'verdict' = 'deplace' AND (e->>'book_id')::bigint = b4
                      AND e->>'book_titulo' = (SELECT titulo FROM public.books WHERE id = b4)
                      AND (e->>'row_id')::bigint = r5 AND e->>'code' = '33700003470461')
       AND NOT (v_rap1 ? 'items_set_aside')
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce((v_rap->'items_set_aside' - 'examples')::text, 'NULL'), 300)
         ||' lot1='||coalesce((v_rap1 ? 'items_set_aside')::text, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T6 ──────────────────────────────────────────────────────────────
  v_t := 'T6 deux Rapprocher (fichier redepose) : un seul brouillon (deja en brouillon) ; la ligne qui n''apporte rien rejetee d''office';
  BEGIN
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src, v_lib, 'essai/l6-pmb-bis.iso', 'l6-pmb-bis.iso', 'marc_iso2709', 'parsed') RETURNING id INTO v_run3;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
    SELECT v_run3, sr.row_no, sr.external_key, sr.item_type, sr.title, sr.subtitle, sr.responsibility_statement, sr.authors, sr.publisher, sr.place_of_publication, sr.publication_year, sr.edition_statement, sr.language, sr.isbn, sr.issn, sr.subjects, sr.raw_payload,
           -- et un exemplaire au code neuf qui porte l'expl_id du brouillon vivant (9002)
           jsonb_set(sr.normalized_payload, '{items}', (sr.normalized_payload->'items')
             || '[{"source_item_code": "L6-AJOUT-2B", "source_item_id": "9002"}]'::jsonb), 'unreviewed', 'pending'
      FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = r2
    RETURNING id INTO rr3;
    PERFORM ingest.fn_match_partner_catalog_run(v_run3);
    v_nx := (SELECT count(*) FROM public.exemplar_drafts);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_reconcile_duplicates(v_run3, ARRAY[rr3]);
    EXECUTE 'RESET ROLE';
    IF (SELECT match_status FROM ingest.partner_catalog_staging_rows WHERE id = rr3) = 'known_record'
       AND (v_res->>'created_items')::int = 0 AND (v_res->>'rows_already_held')::int = 1
       AND (v_res->'verdicts'->>'deja_en_brouillon')::int = 2 AND (v_res->'verdicts'->>'deja_la')::int = 2
       AND (v_res->'verdicts'->>'nouveau')::int = 0
       AND (SELECT count(*) FROM public.exemplar_drafts) = v_nx
       AND (SELECT count(*) FROM public.exemplar_drafts x WHERE x.source_item_code = 'L6-AJOUT-2' AND x.status IN ('draft', 'ready')) = 1
       AND (SELECT (sr.exemplaires_constat->'items'->2->>'draft_id')::bigint = d2
                   AND sr.exemplaires_constat->'items'->2->>'verdict' = 'deja_en_brouillon'
                   AND (sr.exemplaires_constat->'items'->3->>'draft_id')::bigint = d2
                   AND sr.editorial_decision = 'reject'
              FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = rr3)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce((v_res - 'run')::text, 'NULL'), 400)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T7 ──────────────────────────────────────────────────────────────
  v_t := 'T7 publication apres revision : source, run et expl_id poses sur l''exemplaire, sur la notice existante';
  DECLARE v_e bigint;
  BEGIN
    v_res := public.fn_batch_review_request(v_lotL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict((v_res->>'review_id')::bigint, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_e := public.publish_exemplar_draft(d2);
    EXECUTE 'RESET ROLE';
    IF (SELECT e.source_item_code = 'L6-AJOUT-2' AND e.source_item_id = '9002' AND e.import_source_id = v_src
               AND e.import_run_id = v_run2 AND e.library_id = v_lib AND e.tombo ~ '^L6-T-[0-9]{4}$'
               AND e.shelf_location = 'L6 A2'
          FROM public.exemplares e WHERE e.id = v_e)
       AND (SELECT h.book_id FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id = v_e) = b2
       AND (SELECT status FROM public.exemplar_drafts WHERE id = d2) = 'published'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce((SELECT to_jsonb(e) - 'created_at' - 'updated_at' FROM public.exemplares e WHERE e.id = v_e)::text, 'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T8 ──────────────────────────────────────────────────────────────
  v_t := 'T8 corbeille : rapproche a la corbeille, nouveau Rapprocher, sortie de corbeille du premier refusee ; acceptee le code libre';
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_reconcile_duplicates(v_run2, ARRAY[r10]);
    EXECUTE 'RESET ROLE';
    v_lotL2 := (v_res->>'batch_id')::bigint;
    d10 := (SELECT x.id FROM public.exemplar_drafts x WHERE x.import_staging_row_id = r10 AND x.source_item_code = 'L6-CORB-10');
    EXECUTE 'SET LOCAL ROLE authenticated';
    UPDATE public.exemplar_drafts SET status = 'cancelled' WHERE id = d10;
    EXECUTE 'RESET ROLE';
    v_ok := (SELECT editorial_decision = 'pending' AND created_exemplar_draft_id IS NULL FROM ingest.partner_catalog_staging_rows WHERE id = r10);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res2 := public.fn_import_reconcile_duplicates(v_run2, ARRAY[r10]);
    EXECUTE 'RESET ROLE';
    d10b := (SELECT x.id FROM public.exemplar_drafts x WHERE x.import_staging_row_id = r10 AND x.status = 'draft');
    v_hint := NULL;
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = d10;
      EXECUTE 'RESET ROLE';
      v_hint := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT; EXECUTE 'RESET ROLE';
    END;
    -- le code libéré (le second à la corbeille), la sortie est acceptée
    EXECUTE 'SET LOCAL ROLE authenticated';
    UPDATE public.exemplar_drafts SET status = 'cancelled' WHERE id = d10b;
    UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = d10;
    EXECUTE 'RESET ROLE';
    IF v_lotL2 IS NOT NULL AND v_lotL2 <> v_lotL AND NOT (v_res->>'batch_joined')::boolean   -- le lot du run est approuvé : un lot neuf
       AND coalesce(v_ok, false)
       AND d10b IS NOT NULL AND d10b <> d10 AND (v_res2->>'batch_id')::bigint = v_lotL2 AND (v_res2->>'batch_joined')::boolean
       AND v_hint = 'error.import.item_restore_code_taken'
       AND (SELECT status FROM public.exemplar_drafts WHERE id = d10) = 'draft'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : lots '||coalesce(v_lotL2::text, '∅')||'/'||coalesce(v_res2->>'batch_id', '∅')
         ||' reset='||coalesce(v_ok::text, '∅')||' d10b='||coalesce(d10b::text, '∅')||' sortie='||coalesce(v_hint, 'NULL')
         ||' d10='||coalesce((SELECT status FROM public.exemplar_drafts WHERE id = d10), '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T9 ──────────────────────────────────────────────────────────────
  v_t := 'T9 promotion : un exemplaire deplace vers une notice NOUVELLE ecarte de ses brouillons, signale ; la notice se publie sans lui';
  DECLARE v_c jsonb; v_rap jsonb; v_bk bigint;
  BEGIN
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src, v_lib, 'essai/l6-nouvelle.iso', 'l6-nouvelle.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run4;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, raw_payload, normalized_payload, match_status, editorial_decision)
    SELECT v_run4, 1, 'L6-NOUVELLE', 'L6 Notice nouvelle', sr.raw_payload,
           jsonb_set(sr.normalized_payload, '{items}',
             '[{"source_item_code": "33700003669485", "source_item_id": "11", "call_number": "L6 DEPL"},
               {"source_item_code": "L6-NEUF-P", "source_item_id": "9100", "call_number": "L6 NEUF"}]'::jsonb),
           'new_record', 'accept_new'
      FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = r10;
    EXECUTE v_ref INTO v_avant;
    v_res := public.fn_import_promote(v_run4, ARRAY['new_record'], ARRAY['accept_new']);
    v_lot4 := (v_res->>'batch_id')::bigint;
    EXECUTE v_ref INTO v_apres;
    SELECT m.draft_id INTO n4 FROM ingest.partner_catalog_row_to_draft m WHERE m.run_id = v_run4;
    SELECT sr.exemplaires_constat->'items' INTO v_c FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_run4;
    UPDATE public.book_drafts SET bib_ref = 'L6-NOUVELLE-' || id WHERE id = n4;
    v_rap := public.fn_batch_review_report(v_lot4);
    v_res2 := public.fn_batch_review_request(v_lot4);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict((v_res2->>'review_id')::bigint, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    PERFORM public.publish_catalog_batch(v_lot4);
    v_bk := (SELECT published_book_id FROM public.book_drafts WHERE id = n4);
    IF (v_res->>'items_created')::int = 1 AND v_apres = v_avant
       AND (SELECT count(*) FROM public.exemplar_drafts x WHERE x.book_draft_id = n4) = 1
       AND v_c->0 @> jsonb_build_object('verdict', 'deplace', 'exemplar_id', e10, 'book_id', b10)
       AND v_c->1 @> '{"verdict": "nouveau", "code": "L6-NEUF-P"}'::jsonb AND v_c->1 ? 'brouillon_cree'
       AND (v_rap->'items_set_aside'->'counts'->>'deplace')::int = 1
       AND v_bk IS NOT NULL
       -- la notice publiée : le seul « nouveau », aucun exemplaire automatique
       AND (SELECT count(*) FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE h.book_id = v_bk) = 1
       AND (SELECT e.source_item_code = 'L6-NEUF-P' AND e.source_item_id = '9100' AND e.import_run_id = v_run4
              FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE h.book_id = v_bk)
       -- l'exemplaire existant n'a pas bougé
       AND (SELECT h.book_id = b10 AND e.import_run_id = v_run1 AND e.source_item_id = '11'
              FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id = e10)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : promu='||left(coalesce(v_res::text, 'NULL'), 200)
         ||' constat='||left(coalesce(v_c::text, 'NULL'), 400)||' catalogue '||CASE WHEN v_apres = v_avant THEN 'intact' ELSE 'CHANGE' END
         ||' notice='||coalesce(v_bk::text, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T10 ─────────────────────────────────────────────────────────────
  v_t := 'T10 notice restauree de la corbeille : l''exemplaire au code pris depuis y reste ; seul, refuse puis accepte';
  DECLARE v_manuel bigint; v_h2 text;
  BEGIN
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src, v_lib, 'essai/l6-suivre.iso', 'l6-suivre.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run5;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision)
    VALUES (v_run5, 1, 'L6-SUIT', 'L6 Notice qui va et vient',
            '{"items": [{"source_item_code": "L6-SUIT-1", "source_item_id": "9200"}, {"source_item_code": "L6-SUIT-2", "source_item_id": "9201"}]}'::jsonb,
            'new_record', 'accept_new');
    v_lot5 := (public.fn_import_promote(v_run5, ARRAY['new_record'], ARRAY['accept_new'])->>'batch_id')::bigint;
    SELECT m.draft_id INTO n5 FROM ingest.partner_catalog_row_to_draft m WHERE m.run_id = v_run5;
    i5 := (SELECT x.id FROM public.exemplar_drafts x WHERE x.book_draft_id = n5 AND x.source_item_code = 'L6-SUIT-1');
    EXECUTE 'SET LOCAL ROLE authenticated';
    UPDATE public.book_drafts SET status = 'cancelled' WHERE id = n5;
    EXECUTE 'RESET ROLE';
    -- un brouillon fait à la main porte entre-temps le même code
    INSERT INTO public.exemplar_drafts (action, status, label_status, target_library_id, source_item_code, created_by)
    VALUES ('create', 'draft', 'pending', v_lib, 'L6-SUIT-1', v_coord) RETURNING id INTO v_manuel;
    EXECUTE 'SET LOCAL ROLE authenticated';
    UPDATE public.book_drafts SET status = 'draft' WHERE id = n5;
    EXECUTE 'RESET ROLE';
    v_txt := (SELECT string_agg(x.source_item_code || '=' || x.status || '/' || x.cancelled_with_record, ',' ORDER BY x.source_item_code)
                FROM public.exemplar_drafts x WHERE x.book_draft_id = n5);
    v_hint := NULL;
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = i5;
      EXECUTE 'RESET ROLE';
      v_hint := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT; EXECUTE 'RESET ROLE';
    END;
    DELETE FROM public.exemplar_drafts WHERE id = v_manuel;
    v_h2 := NULL;
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = i5;
      EXECUTE 'RESET ROLE';
      v_h2 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h2 = PG_EXCEPTION_HINT; EXECUTE 'RESET ROLE';
    END;
    IF v_txt = 'L6-SUIT-1=cancelled/true,L6-SUIT-2=draft/false'
       AND (SELECT status FROM public.book_drafts WHERE id = n5) = 'draft'
       AND v_hint = 'error.import.item_restore_code_taken'
       AND v_h2 = 'accepte' AND (SELECT status FROM public.exemplar_drafts WHERE id = i5) = 'draft'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : apres restauration '||coalesce(v_txt, '∅')
         ||' seul='||coalesce(v_hint, 'NULL')||' code libre='||coalesce(v_h2, 'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T11 ─────────────────────────────────────────────────────────────
  v_t := 'T11 journal : vivant au code pris, refuse ; a la corbeille, revient avec sa trace (run disparu : le lien seul tombe)';
  DECLARE v_r jsonb; v_h2 text;
  BEGIN
    -- d10b est à la corbeille (T8), d10 vivant porte L6-CORB-10.
    DELETE FROM public.exemplar_drafts WHERE id = d10b;
    SELECT a.id INTO v_audit FROM public.catalog_audit_log a
     WHERE a.action = 'delete' AND a.details->>'source_table' = 'exemplar_drafts'
       AND (a.details->'snapshot'->>'id')::bigint = d10b
     ORDER BY a.id DESC LIMIT 1;
    -- l'instantané rejoué VIVANT, et son run disparu depuis
    UPDATE public.catalog_audit_log
       SET details = jsonb_set(jsonb_set(details, '{snapshot,status}', '"draft"'), '{snapshot,import_run_id}', '999999999')
     WHERE id = v_audit;
    v_hint := NULL;
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_r := public.fn_restore_deleted_draft(v_audit);
      EXECUTE 'RESET ROLE';
      v_hint := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT; EXECUTE 'RESET ROLE';
    END;
    UPDATE public.catalog_audit_log SET details = jsonb_set(details, '{snapshot,status}', '"cancelled"') WHERE id = v_audit;
    v_h2 := NULL;
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_r := public.fn_restore_deleted_draft(v_audit);
      EXECUTE 'RESET ROLE';
      v_h2 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h2 = PG_EXCEPTION_HINT; v_h2 := coalesce(nullif(v_h2, ''), SQLERRM); EXECUTE 'RESET ROLE';
    END;
    IF v_audit IS NOT NULL AND v_hint = 'error.import.item_restore_code_taken'
       AND v_h2 = 'accepte'
       AND (SELECT x.status = 'cancelled' AND x.import_run_id IS NULL AND x.import_source_id = v_src AND x.source_item_id = '9010'
                   AND x.source_item_code = 'L6-CORB-10'
              FROM public.exemplar_drafts x WHERE x.id = d10b)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : journal='||coalesce(v_audit::text, '∅')||' vivant='||coalesce(v_hint, 'NULL')
         ||' corbeille='||coalesce(v_h2, 'NULL')||' '||coalesce((SELECT to_jsonb(x) - 'created_at' - 'updated_at' FROM public.exemplar_drafts x WHERE x.id = d10b)::text, 'absent')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T12 ─────────────────────────────────────────────────────────────
  v_t := 'T12 meme expl_id et meme code dans deux bibliotheques : deux exemplaires distincts, chaque constat chez soi';
  DECLARE v_c jsonb; v_d bigint;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coordB, 'role', 'authenticated')::text, true);
    INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
    VALUES ('L6 PMB de B', v_libB, 'mapeada', 'own_catalog', true) RETURNING id INTO v_srcB;
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_srcB, v_libB, 'essai/l6-b.iso', 'l6-b.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_runB;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision)
    VALUES (v_runB, 1, 'B-1', 'L6 Notice de B',
            '{"items": [{"source_item_code": "33700004388761", "source_item_id": "1", "call_number": "B 1"}]}'::jsonb,
            'new_record', 'accept_new');
    v_lotB := (public.fn_import_promote(v_runB, ARRAY['new_record'], ARRAY['accept_new'])->>'batch_id')::bigint;
    SELECT sr.exemplaires_constat->'items' INTO v_c FROM ingest.partner_catalog_staging_rows sr WHERE sr.run_id = v_runB;
    SELECT m.draft_id INTO v_d FROM ingest.partner_catalog_row_to_draft m WHERE m.run_id = v_runB;
    UPDATE public.book_drafts SET bib_ref = 'L6-B-' || id WHERE id = v_d;
    v_res := public.fn_batch_review_request(v_lotB);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict((v_res->>'review_id')::bigint, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coordB, 'role', 'authenticated')::text, true);
    PERFORM public.publish_catalog_batch(v_lotB);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    IF v_c->0 @> '{"verdict": "nouveau"}'::jsonb
       AND (SELECT count(*) FROM public.exemplares e WHERE e.source_item_id = '1' AND e.source_item_code = '33700004388761') = 2
       AND (SELECT count(DISTINCT e.library_id) FROM public.exemplares e WHERE e.source_item_id = '1' AND e.source_item_code = '33700004388761') = 2
       AND (SELECT e.import_source_id = v_srcB AND e.import_run_id = v_runB AND e.tombo ~ '^L6B-T-'
              FROM public.exemplares e WHERE e.library_id = v_libB AND e.source_item_id = '1')
       AND (SELECT e.import_run_id FROM public.exemplares e WHERE e.id = e1) = v_run1
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : constat='||coalesce(v_c::text, 'NULL')||' exemplaires expl_id 1 : '
         ||(SELECT count(*) FROM public.exemplares e WHERE e.source_item_id = '1')); END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T13 ─────────────────────────────────────────────────────────────
  v_t := 'T13 unicite par bibliotheque : index ; publication refusee (HINT) pour un identifiant deja pris';
  DECLARE v_etat text; v_d bigint;
  BEGIN
    v_etat := NULL;
    BEGIN
      UPDATE public.exemplares SET source_item_id = '1' WHERE id = e4;
      v_etat := 'accepte';
    EXCEPTION WHEN unique_violation THEN GET STACKED DIAGNOSTICS v_etat = CONSTRAINT_NAME;
    END;
    INSERT INTO public.exemplar_drafts (action, status, label_status, target_library_id, target_bib_ref, source_item_id, import_source_id, created_by)
    SELECT 'create', 'draft', 'pending', v_lib, b.bib_ref, '1', v_src, v_coord FROM public.books b WHERE b.id = b1
    RETURNING id INTO v_d;
    v_hint := NULL;
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      PERFORM public.publish_exemplar_draft(v_d);
      EXECUTE 'RESET ROLE';
      v_hint := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT; EXECUTE 'RESET ROLE';
    END;
    IF v_etat = 'exemplares_source_item_id_par_source'
       AND v_hint = 'error.publish.source_item_id_taken'
       AND (SELECT count(*) FROM public.exemplares e WHERE e.library_id = v_lib AND e.import_source_id = v_src AND e.source_item_id = '1') = 1
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : index='||coalesce(v_etat, 'NULL')||' publication='||coalesce(v_hint, 'NULL')); END IF;
    DELETE FROM public.exemplar_drafts WHERE id = v_d;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T14 ─────────────────────────────────────────────────────────────
  v_t := 'T14 l''API ne pose pas la trace : INSERT et UPDATE des brouillons refuses (HINT) ; exemplares sans ecriture API ; constat hors API';
  DECLARE v_h text[] := ARRAY[]::text[]; v_x text; v_n2 int; v_trace text;
  BEGIN
    SELECT x.source_item_id || '|' || x.import_source_id || '|' || x.import_run_id INTO v_trace FROM public.exemplar_drafts x WHERE x.id = d10;
    EXECUTE 'SET LOCAL ROLE authenticated';
    FOR v_x IN SELECT unnest(ARRAY[
        'INSERT INTO public.exemplar_drafts (action, status, label_status, target_library_id, source_item_id) VALUES (''create'', ''draft'', ''pending'', ''' || v_lib || ''', ''L6-API'')',
        'INSERT INTO public.exemplar_drafts (action, status, label_status, target_library_id, import_run_id) VALUES (''create'', ''draft'', ''pending'', ''' || v_lib || ''', ' || v_run2 || ')',
        'INSERT INTO public.exemplar_drafts (action, status, label_status, target_library_id, import_source_id) VALUES (''create'', ''draft'', ''pending'', ''' || v_lib || ''', ' || v_src || ')',
        'UPDATE public.exemplar_drafts SET source_item_id = ''L6-API'' WHERE id = ' || d10,
        'UPDATE public.exemplar_drafts SET import_run_id = NULL WHERE id = ' || d10,
        'UPDATE public.exemplar_drafts SET import_source_id = NULL WHERE id = ' || d10])
    LOOP
      BEGIN
        EXECUTE v_x;
        v_h := v_h || 'accepte'::text;
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT; v_h := v_h || (SQLSTATE || ':' || coalesce(v_hint, ''));
      END;
    END LOOP;
    -- témoin : une retouche ordinaire passe, la trace reste
    UPDATE public.exemplar_drafts SET notes = 'L6 note API' WHERE id = d10;
    -- exemplares : aucune écriture par l'API (RLS)
    BEGIN
      INSERT INTO public.exemplares (bib_ref, tombo, library_id, circulation_policy, source_item_id)
      VALUES ('X', 'L6-API-T', v_lib, 'consulta', 'L6-API');
      v_h := v_h || 'accepte'::text;
    EXCEPTION WHEN OTHERS THEN v_h := v_h || (SQLSTATE || ':rls');
    END;
    UPDATE public.exemplares SET source_item_id = 'L6-API', import_run_id = NULL WHERE id = e1;
    GET DIAGNOSTICS v_n2 = ROW_COUNT;
    EXECUTE 'RESET ROLE';
    IF v_h = ARRAY['42501:error.import.item_trace_reserved', '42501:error.import.item_trace_reserved', '42501:error.import.item_trace_reserved',
                   '42501:error.import.item_trace_reserved', '42501:error.import.item_trace_reserved', '42501:error.import.item_trace_reserved',
                   '42501:rls']
       AND (SELECT x.source_item_id || '|' || x.import_source_id || '|' || x.import_run_id FROM public.exemplar_drafts x WHERE x.id = d10) = v_trace
       AND (SELECT notes FROM public.exemplar_drafts WHERE id = d10) = 'L6 note API'
       AND v_n2 = 0 AND (SELECT e.source_item_id = '1' AND e.import_run_id = v_run1 FROM public.exemplares e WHERE e.id = e1)
       AND NOT has_table_privilege('authenticated', 'ingest.partner_catalog_staging_rows', 'UPDATE')
       AND NOT has_table_privilege('anon', 'ingest.partner_catalog_staging_rows', 'UPDATE')
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_h, ' ; ')||' / maj exemplares='||coalesce(v_n2::text, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T15 ─────────────────────────────────────────────────────────────
  v_t := 'T15 rejet d''office seulement quand la ligne n''apporte rien ; une ligne signalee se reconstate sans rien creer ; lots 4/5 coherents';
  DECLARE v_prep jsonb;
  BEGIN
    v_nx := (SELECT count(*) FROM public.exemplar_drafts);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_reconcile_duplicates(v_run2, ARRAY[r3]);
    PERFORM public.fn_import_recomparer(v_run2, ARRAY[r5]);
    v_prep := public.fn_import_preparer_mises_a_jour(v_run2, ARRAY[r5]);
    EXECUTE 'RESET ROLE';
    IF (v_res->>'requested_rows')::int = 1 AND (v_res->>'rows_signalled')::int = 1 AND (v_res->>'created_items')::int = 0
       AND coalesce((v_res->>'skipped_rows')::int, 0) = 0
       AND (SELECT count(*) FROM public.exemplar_drafts) = v_nx
       AND (SELECT editorial_decision FROM ingest.partner_catalog_staging_rows WHERE id = r3) = 'accept_duplicate'
       -- seules les lignes qui n'apportent rien sont rejetées, et le rejet est reconnu comme automatique
       AND (SELECT count(*) FROM ingest.partner_catalog_staging_rows
             WHERE run_id = v_run2 AND editorial_decision = 'reject') = 1
       AND NOT EXISTS (SELECT 1 FROM ingest.partner_catalog_staging_rows
                        WHERE id IN (r1, r3, r5, r6, r7, r8)
                          AND ingest.fn_h21_rejet_par_choix(editorial_decision, editorial_note, discarded_draft_id))
       -- « Préparer la mise à jour » traite la ligne signalée (lot 4)
       AND (v_prep->>'prepared')::int = 1
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce((v_res - 'run')::text, 'NULL'), 200)
         ||' preparation='||left(coalesce(v_prep::text, 'NULL'), 200)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T16 ─────────────────────────────────────────────────────────────
  v_t := 'T16 profil : id_tag / id_code / id_prefix acceptes ; hors forme refuses (HINT)';
  DECLARE v_h text[] := ARRAY[]::text[]; v_m jsonb;
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    FOR v_m IN SELECT unnest(ARRAY['{"id_tag": "996", "id_code": "9", "id_prefix": "expl_id:"}', '{"id_tag": ""}',
                                   '{"id_tag": "99"}', '{"id_code": "ab"}', '{"id_prefix": "a b"}', '{"id_inconnu": "x"}']::jsonb[])
    LOOP
      BEGIN
        PERFORM public.fn_import_profile_create(v_lib, 'L6 profil ' || md5(v_m::text), '{}'::jsonb, '{}'::jsonb, v_m);
        v_h := v_h || 'accepte'::text;
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT; v_h := v_h || coalesce(v_hint, SQLERRM);
      END;
    END LOOP;
    EXECUTE 'RESET ROLE';
    IF v_h = ARRAY['accepte', 'accepte', 'error.import.items_mapping_invalid', 'error.import.items_mapping_invalid',
                   'error.import.items_mapping_invalid', 'error.import.items_mapping_invalid']
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_h, ' ; ')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T17 ─────────────────────────────────────────────────────────────
  v_t := 'T17 structure et droits : aides fermees, portes inchangees, declencheurs, aucune ecriture API sur exemplares';
  DECLARE v_f text; v_e text := '';
  BEGIN
    FOREACH v_f IN ARRAY ARRAY['ingest.fn_h21_exemplaire_pris(uuid, text, text, bigint, bigint, bigint)',
                               'ingest.fn_h21_constat_exemplaire(uuid, bigint, bigint, text, text)',
                               'ingest.fn_h21_lot_ouvert_du_run(bigint, uuid)', 'ingest.fn_h21_trace_exemplaire_rejouable(jsonb)',
                               'public.tg_exemplar_drafts_code_libre_au_retour()',
                               'ingest.fn_create_exemplar_drafts_from_import_rows(bigint, bigint[], text, text, uuid)',
                               'ingest.fn_create_item_drafts_for_batch(bigint, uuid, bigint[])'] LOOP
      IF has_function_privilege('authenticated', v_f, 'EXECUTE') OR has_function_privilege('anon', v_f, 'EXECUTE') THEN
        v_e := v_e || ' ouverte:' || v_f;
      END IF;
    END LOOP;
    FOREACH v_f IN ARRAY ARRAY['public.fn_import_list_run_rows(bigint)', 'public.fn_batch_review_report(bigint)',
                               'public.fn_import_reconcile_duplicates(bigint, bigint[])', 'public.publish_exemplar_draft(bigint)',
                               'public.fn_restore_deleted_draft(bigint)', 'public.fn_import_profile_create(uuid, text, jsonb, jsonb, jsonb)'] LOOP
      IF NOT has_function_privilege('authenticated', v_f, 'EXECUTE') OR has_function_privilege('anon', v_f, 'EXECUTE') THEN
        v_e := v_e || ' porte:' || v_f;
      END IF;
    END LOOP;
    IF NOT EXISTS (SELECT 1 FROM pg_trigger t WHERE t.tgrelid = 'public.exemplar_drafts'::regclass
                    AND t.tgname = 'exemplar_drafts_zx_code_libre_au_retour' AND NOT t.tgisinternal) THEN
      v_e := v_e || ' declencheur-corbeille';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = 'public.exemplares'::regclass AND p.polcmd IN ('a', 'w', '*')) THEN
      v_e := v_e || ' politique-ecriture-exemplares';
    END IF;
    IF (SELECT count(*) FROM pg_constraint c WHERE c.contype = 'f' AND c.confdeltype = 'n'
         AND c.conname IN ('exemplares_import_source_id_fkey', 'exemplares_import_run_id_fkey',
                           'exemplar_drafts_import_source_id_fkey', 'exemplar_drafts_import_run_id_fkey')) <> 4 THEN
      v_e := v_e || ' fk';
    END IF;
    IF v_e = '' THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' :'||v_e); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T19 ─────────────────────────────────────────────────────────────
  v_t := 'T19 « Editer » un exemplaire importe : la reprise ne recopie pas la trace, sa publication ne l''efface pas';
  DECLARE v_d bigint; v_av text;
  BEGIN
    SELECT e.source_item_id || '|' || e.import_source_id || '|' || e.import_run_id || '|' || e.source_item_code INTO v_av
      FROM public.exemplares e WHERE e.id = e1;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_d := public.create_exemplar_draft_from_exemplar(e1, NULL);
    UPDATE public.exemplar_drafts SET notes = 'L6 retouche' WHERE id = v_d;
    PERFORM public.publish_exemplar_draft(v_d);
    EXECUTE 'RESET ROLE';
    IF (SELECT x.source_item_id IS NULL AND x.import_source_id IS NULL AND x.import_run_id IS NULL
          FROM public.exemplar_drafts x WHERE x.id = v_d)
       AND (SELECT e.source_item_id || '|' || e.import_source_id || '|' || e.import_run_id || '|' || e.source_item_code
              FROM public.exemplares e WHERE e.id = e1) = v_av
       AND (SELECT notes FROM public.exemplares WHERE id = e1) = 'L6 retouche'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : avant='||coalesce(v_av, '∅')||' apres='
         ||coalesce((SELECT e.source_item_id || '|' || e.import_source_id || '|' || e.import_run_id FROM public.exemplares e WHERE e.id = e1), '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T20 ─────────────────────────────────────────────────────────────
  v_t := 'T20 corbeille : un brouillon dont le code, ou l''expl_id, est pris par un EXEMPLAIRE publie ne sort pas';
  DECLARE v_c1 bigint; v_c2 bigint; v_h1 text; v_h2 text;
  BEGIN
    -- d2 est publié (T7) : L6-AJOUT-2 / 9002 sont à un exemplaire de BLMF
    INSERT INTO public.exemplar_drafts (action, status, label_status, target_library_id, source_item_code, created_by)
    VALUES ('create', 'cancelled', 'pending', v_lib, 'L6-AJOUT-2', v_coord) RETURNING id INTO v_c1;
    INSERT INTO public.exemplar_drafts (action, status, label_status, target_library_id, source_item_code, source_item_id, import_source_id, created_by)
    VALUES ('create', 'cancelled', 'pending', v_lib, 'L6-AUTRE-CODE', '9002', v_src, v_coord) RETURNING id INTO v_c2;
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = v_c1;
      EXECUTE 'RESET ROLE';
      v_h1 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h1 = PG_EXCEPTION_HINT; EXECUTE 'RESET ROLE';
    END;
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = v_c2;
      EXECUTE 'RESET ROLE';
      v_h2 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h2 = PG_EXCEPTION_HINT; EXECUTE 'RESET ROLE';
    END;
    IF v_h1 = 'error.import.item_restore_code_taken' AND v_h2 = 'error.import.item_restore_code_taken'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : code='||coalesce(v_h1, 'NULL')||' expl_id='||coalesce(v_h2, 'NULL')); END IF;
    DELETE FROM public.exemplar_drafts WHERE id IN (v_c1, v_c2);
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T21 ─────────────────────────────────────────────────────────────
  v_t := 'T21 une ligne sans exemplaire decrit (CSV, normalized_payload absent) garde l''exemplaire implicite d''avant (H19) : un brouillon, constate « nouveau, implicite »';
  DECLARE v_row bigint; v_r7 bigint;
  BEGIN
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src, v_lib, 'essai/l6-csv.csv', 'l6-csv.csv', 'csv', 'ready_for_review') RETURNING id INTO v_r7;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, match_status, editorial_decision, proposed_book_id)
    VALUES (v_r7, 1, 'L6-CSV-1', 'L6 Ligne de CSV', 'matched_book', 'pending', b1) RETURNING id INTO v_row;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_reconcile_duplicates(v_r7, ARRAY[v_row]);
    EXECUTE 'RESET ROLE';
    IF (v_res->>'created_items')::int = 1 AND (v_res->>'rows_already_held')::int = 0
       AND (SELECT sr.exemplaires_constat->'items' = '[{"n": 1, "code": null, "expl_id": null, "cote": null, "verdict": "nouveau", "implicite": true}]'::jsonb
                   OR (sr.exemplaires_constat->'items'->0 @> '{"verdict": "nouveau", "implicite": true}'::jsonb
                       AND jsonb_array_length(sr.exemplaires_constat->'items') = 1)
              FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_row)
       AND (SELECT editorial_decision FROM ingest.partner_catalog_staging_rows WHERE id = v_row) = 'accept_duplicate'
       AND (SELECT count(*) FROM public.exemplar_drafts x WHERE x.import_staging_row_id = v_row AND x.source_item_code IS NULL
              AND x.import_run_id = v_r7 AND x.import_source_id = v_src) = 1
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce((v_res - 'run')::text, 'NULL'), 300)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T22 ─────────────────────────────────────────────────────────────
  v_t := 'T22 l''expl_id appartient a sa SOURCE : second PMB de la meme bibliotheque (expl_id 1 a nouveau) — nouveau, publies tous deux ; nouvel export du meme PMB, nouvelle source — reconnu par le code, sans reetiquete';
  DECLARE v_src2 bigint; v_src3 bigint; v_r7 bigint; v_r8 bigint; v_row2 bigint; v_row3 bigint; v_lot bigint; v_c2 jsonb; v_c3 jsonb; v_res3 jsonb;
  BEGIN
    INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
    VALUES ('L6 Second PMB', v_lib, 'mapeada', 'own_catalog', true) RETURNING id INTO v_src2;
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src2, v_lib, 'essai/l6-s2.iso', 'l6-s2.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_r7;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision, proposed_book_id)
    VALUES (v_r7, 1, 'S2-1', 'L6 S2',
            '{"items": [{"source_item_code": "S2-0001", "source_item_id": "1"}, {"source_item_code": "S2-0002", "source_item_id": "77777"}]}'::jsonb,
            'matched_book', 'pending', b2) RETURNING id INTO v_row2;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_reconcile_duplicates(v_r7, ARRAY[v_row2]);
    EXECUTE 'RESET ROLE';
    v_lot := (v_res->>'batch_id')::bigint;
    SELECT sr.exemplaires_constat->'items' INTO v_c2 FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_row2;
    v_res2 := public.fn_batch_review_request(v_lot);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict((v_res2->>'review_id')::bigint, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    PERFORM public.publish_catalog_batch(v_lot);
    -- un nouvel export du MÊME PMB, déposé comme nouvelle source : reconnu par le
    -- code ; son expl_id 6 (celui de l'exemplaire du rang 6 dans la première
    -- source) ne dit rien d'un autre exemplaire
    INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
    VALUES ('L6 Meme PMB, nouvelle source', v_lib, 'mapeada', 'own_catalog', true) RETURNING id INTO v_src3;
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src3, v_lib, 'essai/l6-s3.iso', 'l6-s3.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_r8;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision, proposed_book_id)
    VALUES (v_r8, 1, 'S3-1', 'L6 S3',
            -- le code de l'exemplaire du rang 1 avec l'expl_id 6, un code neuf avec l'expl_id 1 : ces
            -- expl_id sont ceux d'AUTRES exemplaires de la première source — ici, ils ne disent rien
            '{"items": [{"source_item_code": "33700004388761", "source_item_id": "6"}, {"source_item_code": "S3-NEW", "source_item_id": "1"},
                        {"source_item_code": "S3-NEW2", "source_item_id": "515151"}]}'::jsonb,
            'matched_book', 'pending', b1) RETURNING id INTO v_row3;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res3 := public.fn_import_reconcile_duplicates(v_r8, ARRAY[v_row3]);
    EXECUTE 'RESET ROLE';
    SELECT sr.exemplaires_constat->'items' INTO v_c3 FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = v_row3;
    -- la corbeille aussi : un brouillon de la nouvelle source à l'expl_id 2 sort (l'expl_id 2 de la
    -- première source, celui de l'exemplaire du rang 2, ne le retient pas)
    INSERT INTO public.exemplar_drafts (action, status, label_status, target_library_id, source_item_code, source_item_id, import_source_id, created_by)
    VALUES ('create', 'cancelled', 'pending', v_lib, 'S3-ZZ', '2', v_src3, v_coord) RETURNING id INTO v_id;
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = v_id;
      EXECUTE 'RESET ROLE';
      v_hint := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT; EXECUTE 'RESET ROLE';
    END;
    -- et un brouillon du second PMB à l'expl_id 515151, que porte un brouillon VIVANT de la
    -- nouvelle source (S3-NEW2) : il sort aussi
    INSERT INTO public.exemplar_drafts (action, status, label_status, target_library_id, source_item_code, source_item_id, import_source_id, created_by)
    VALUES ('create', 'cancelled', 'pending', v_lib, 'S2-ZZ', '515151', v_src2, v_coord) RETURNING id INTO v_id;
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = v_id;
      EXECUTE 'RESET ROLE';
      v_hint := v_hint || '+accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_txt = PG_EXCEPTION_HINT; v_hint := v_hint || '+' || coalesce(v_txt, 'NULL'); EXECUTE 'RESET ROLE';
    END;
    IF v_res->'verdicts' = '{"nouveau": 2, "deja_la": 0, "deja_en_brouillon": 0, "sans_code": 0, "deplace": 0, "reetiquete": 0, "code_repris": 0}'::jsonb
       AND v_c2->0 @> '{"verdict": "nouveau", "expl_id": "1"}'::jsonb
       -- publiés tous deux ; deux exemplaires de BLMF à l'expl_id 1, de deux sources
       AND (SELECT count(*) FROM public.exemplares e WHERE e.library_id = v_lib AND e.import_source_id = v_src2) = 2
       AND (SELECT count(DISTINCT e.import_source_id) FROM public.exemplares e WHERE e.library_id = v_lib AND e.source_item_id = '1') = 2
       AND v_res3->'verdicts' = '{"nouveau": 2, "deja_la": 1, "deja_en_brouillon": 0, "sans_code": 0, "deplace": 0, "reetiquete": 0, "code_repris": 0}'::jsonb
       AND v_c3->0 @> jsonb_build_object('verdict', 'deja_la', 'exemplar_id', e1)
       AND v_c3->1 @> '{"verdict": "nouveau", "code": "S3-NEW"}'::jsonb
       AND v_hint = 'accepte+accepte'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : S2='||coalesce(v_c2::text, 'NULL')||' S3='||coalesce(v_c3::text, 'NULL')
         ||' publies='||(SELECT count(*) FROM public.exemplares e WHERE e.import_source_id = v_src2)||' corbeille='||coalesce(v_hint, 'NULL')); END IF;
  EXCEPTION WHEN OTHERS THEN
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T23 ─────────────────────────────────────────────────────────────
  v_t := 'T23 ligne MARC lue avec sa zone d''exemplaire (item_tag) qui n''en decrit aucun : Rapprocher ne cree rien, la ligne n''apporte rien ; redeposee, toujours rien';
  DECLARE v_run bigint; v_row bigint; v_r2 jsonb;
  BEGIN
    v_nx := (SELECT count(*) FROM public.exemplar_drafts);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_reconcile_duplicates(v_run2, ARRAY[r20]);
    EXECUTE 'RESET ROLE';
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src, v_lib, 'essai/l6-redepose.iso', 'l6-redepose.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, raw_payload, normalized_payload, match_status, editorial_decision, proposed_book_id)
    SELECT v_run, row_no, external_key, title, raw_payload, normalized_payload, 'known_record', 'pending', proposed_book_id
      FROM ingest.partner_catalog_staging_rows WHERE id = r20 RETURNING id INTO v_row;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_r2 := public.fn_import_reconcile_duplicates(v_run, ARRAY[v_row]);
    EXECUTE 'RESET ROLE';
    IF (SELECT raw_payload->>'item_tag' FROM ingest.partner_catalog_staging_rows WHERE id = r20) = '995'
       AND (v_res->>'created_items')::int = 0 AND (v_res->>'rows_already_held')::int = 1
       AND (v_r2->>'created_items')::int = 0 AND (v_r2->>'rows_already_held')::int = 1
       AND (SELECT count(*) FROM public.exemplar_drafts) = v_nx
       AND (SELECT count(*) FROM ingest.partner_catalog_staging_rows sr
             WHERE sr.id IN (r20, v_row) AND sr.editorial_decision = 'reject'
               AND sr.editorial_note LIKE 'Todos os exemplares desta linha ja estao na biblioteca%nenhum exemplar%'
               AND NOT ingest.fn_h21_rejet_par_choix(sr.editorial_decision, sr.editorial_note, sr.discarded_draft_id)
               AND sr.exemplaires_constat->'items' = '[]'::jsonb
               AND (sr.exemplaires_constat->>'sans_exemplaire_decrit')::boolean) = 2
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce((v_res - 'run')::text, 'NULL'), 200)
         ||' redepose='||left(coalesce((v_r2 - 'run')::text, 'NULL'), 200)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T18 ─────────────────────────────────────────────────────────────
  v_t := 'T18 mesure : Rapprocher une ligne de 300 exemplaires sous le jeton de la coordination, < 8 s';
  DECLARE v_row bigint;
  BEGIN
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src, v_lib, 'essai/l6-mesure.iso', 'l6-mesure.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run6;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision, proposed_book_id)
    SELECT v_run6, 1, 'L6-MESURE', 'L6 Mesure',
           jsonb_build_object('items', (SELECT jsonb_agg(jsonb_build_object('source_item_code', 'L6M-' || g, 'source_item_id', 'M' || g,
                                                                          'call_number', 'M ' || g)) FROM generate_series(1, 300) g)),
           'matched_book', 'pending', b1
    RETURNING id INTO v_row;
    ANALYZE public.exemplares, public.exemplar_drafts;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_t0 := clock_timestamp();
    v_res := public.fn_import_reconcile_duplicates(v_run6, ARRAY[v_row]);
    v_ms := extract(epoch FROM clock_timestamp() - v_t0) * 1000;
    EXECUTE 'RESET ROLE';
    RAISE NOTICE 'H21L6A-MESURE Rapprocher une ligne de 300 exemplaires (300 constats, 300 brouillons) : % ms', round(v_ms);
    IF (v_res->>'created_items')::int = 300 AND v_ms < 8000
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce((v_res - 'run')::text, 'NULL'), 200)||' ; '||round(v_ms)||' ms'); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  IF v_failed = 0 THEN
    RAISE EXCEPTION 'H21-LOT6A-EXEMPLAIRES OK : %/% tests passés', v_passed, v_passed;
  ELSE
    RAISE EXCEPTION 'H21-LOT6A-EXEMPLAIRES ECHEC : %/% OK, % échec(s) | %', v_passed, v_passed + v_failed, v_failed, array_to_string(v_failures, ' || ');
  END IF;
END $$;
